import{_ as t,l as n,o as e,c as s,v as i,p as l,x as r,d as h,i as E,S as p}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"Morris–Shin 公共信息","description":"","frontmatter":{"title":"Morris–Shin 公共信息","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/morris-shin-public-info.md","filePath":"econ/morris-shin-public-info.md","lastUpdated":1789023840000}'),d={name:"econ/morris-shin-public-info.md"};function c(A,a,m,B,_,u){const o=n("Mermaid");return e(),s("div",null,[a[1]||(a[1]=i('<h1 id="morris–shin-公共信息" tabindex="-1">Morris–Shin 公共信息 <a class="header-anchor" href="#morris–shin-公共信息" aria-label="Permalink to &quot;Morris–Shin 公共信息&quot;">​</a></h1><div class="epigraph"><p>在协调博弈里，公共信号被用作公共知识；精度一般的公告，也可以被过度加权到损害配置。</p><footer>—— Morris and Shin, Social Value of Public Information, American Economic Review, 2002</footer></div><p><a href="/econ/beauty-contest-higher-order">上一课</a>已经把价格写成高阶期望的加权和，公共噪声更持久。本课缺口是<strong>福利</strong>：多披露一点公共信息，是否一定更好。Morris 与 Shin（2002）给出否定的参数区。不重推高阶展开，不写央行沟通实证。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>标准贝叶斯决策：更多公共信息降低对 \\(\\theta\\) 的均方误差，私人与社会都受益。美人竞赛改变目标：每人要同时贴近 \\(\\theta\\) 与贴近别人的平均行动。公共信号 \\(y\\) 是公共知识，它移动整个平均行动，因而在「贴近别人」那一项里特别值钱。均衡里 \\(y\\) 的权重超过它作为 \\(\\theta\\) 之信号的精度所配得的权重——上一课已有。</p><p>福利缺口是：过度加权把公共噪声写进集体行动。若协调项在社会目标里权重低于私人目标（私人过度在意相对表现），则提高 \\(y\\) 的精度可能放大噪声、降低福利。私有信号没有这个问题：它不构成公共知识，加总时误差相消。</p><p><span class="marginnote">Morris and Shin, <em>AER</em> 92(5), 2002。原文动机含金融市场与货币政策透明。本课只保留协调博弈的逻辑，不审某一家央行的新闻稿。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>二次损失：距离 \\(\\theta\\) 的项，加上距离平均行动的项。均衡行动线性于 \\((y,x_i)\\)。社会若只在乎对 \\(\\theta\\) 的配置（或给协调项较小权重），最优权重接近贝叶斯；均衡权重偏向 \\(y\\)。比较静态：\\(\\mathrm{Var}(y\\mid\\theta)\\) 下降时，均衡把更多噪声以更强系数写进平均行动，净福利可以下降——当且仅当协调动机足够强、公共信号还不够准到把噪声本身压没。</p><p>与 GS 对照：GS 的公共对象是价格，泄漏降低采集。这里的公共对象是外生公告 \\(y\\)，泄漏（其实是公共知识）提高协调价值、扭曲权重。获取课的互补，在此有了福利符号：私人过度投资于 \\(y\\)。</p>',10)),(e(),l(p,null,{default:r(()=>[E(o,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20Y%5B%22%E5%85%AC%E5%85%B1%E4%BF%A1%E5%8F%B7%20y%22%5D%20--%3E%20CK%5B%22%E5%85%AC%E5%85%B1%E7%9F%A5%E8%AF%86%22%5D%0A%20%20CK%20--%3E%20W%5B%22%E5%9D%87%E8%A1%A1%E8%BF%87%E5%BA%A6%E5%8A%A0%E6%9D%83%22%5D%0A%20%20W%20--%3E%20NOISE%5B%22%E5%85%AC%E5%85%B1%E5%99%AA%E5%A3%B0%E8%BF%9B%E5%85%A5%E5%B9%B3%E5%9D%87%E8%A1%8C%E5%8A%A8%22%5D%0A%20%20NOISE%20--%3E%20WEL%5B%22%E7%A4%BE%E4%BC%9A%E4%BB%B7%E5%80%BC%E5%8F%AF%E4%BB%A5%E4%B8%BA%E8%B4%9F%22%5D%0A%20%20PRIV%5B%22%E7%A7%81%E6%9C%89%E4%BF%A1%E5%8F%B7%22%5D%20--%3E%20LLN%5B%22%E5%8A%A0%E6%80%BB%E7%9B%B8%E6%B6%88%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=i('<p>不要把「少披露」写成微观结构里的知情交易隐藏。那是战略交易者对 Kyle 风格 \\(\\lambda\\) 的反应；本课没有做市商。政策含义若要落到「公告与订单流谁先到」，已经越过 <a href="/econ/to-limit-order-book">到限价簿</a> 的切点。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是公共知识。\\(y\\) 被看见，且人人知道人人看见，高阶期望坍缩到 \\(y\\) 上。私有 \\(x_i\\) 即使精度更高，也不能同样移动别人的二阶信念。于是理性的人「明知 \\(y\\) 噪，仍跟 \\(y\\)」——因为别人跟。福利损失是集体跟错，不是个人算错贝叶斯。</p><p>信息披露后课会问企业愿不愿意把 \\(y\\) 造出来。本课 \\(y\\) 外生，只钉社会价值的符号可以翻。中介课则把 \\(y\\) 变成评级：公共信号的生产本身是产业。</p><p><span class="marginnote">Angeletos–Pavan 把「社会是否也需要协调」参数化：若社会目标与私人一样需要协调，公共信息的价值转正。符号取决于两种损失的相对权重，不是一句「透明总好」或「透明总坏」。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把本课写成反对一切披露。精度足够高时，噪声项被压住，价值转正；社会本身需要协调时，价值更不会负。刀刃在参数。也不要把过度加权检验写成事件研究的 PEAD——上一课程的注意力漂移是处理失败；这里是处理成功之后的战略权重。</p><p>下一课把战略换成有市场力的知情交易者：Kyle 在均衡框架里的位置。公共公告与私有信息的博弈，从权重问题变成「信息如何进入价格冲击」。</p><p>后课默认：协调下公共信息可被过度加权；其社会价值不必为正。私有信息加总更干净。这不改写 EMH 的信息分层，只限制「多披露必帕累托改进」。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>公共知识使 \\(y\\) 的均衡权重超过贝叶斯权重。</li><li>协调动机足够强时，提高公共精度可以降低福利。</li><li>符号依赖社会是否同样需要协调，不是反披露教条。</li><li>出处：Morris and Shin, <em>AER</em> 2002。</li></ul>',11))])}const b=t(d,[["render",c]]);export{S as __pageData,b as default};
